name: Auto‑approve workflows for first‑time contributors

on:
  pull_request_target:
    types: [labeled, synchronize]
    branches:
      - main
      - release-**

permissions:
  contents: read

jobs:
  approve:
    if: github.event.pull_request.head.repo.full_name == github.repository
    runs-on: ubuntu-latest
    permissions:
      actions: write
    steps:
      - name: Determine if contributor is returning or has ok‑to‑test label
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const author = pr.user.login;
            const labels = pr.labels.map(l => l.name);
            const hasOkToTest = labels.includes('ok-to-test');

            // Count all PRs by this author
            const perPage = 100;
            let page = 1;
            let prCount = 0;
            while (true) {
              const { data } = await github.pulls.list({
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'all',
                per_page: perPage,
                page: page,
                author: author
              });
              prCount += data.length;
              if (data.length < perPage) break;
              page++;
            }

            const isReturning = prCount > 1;
            core.setOutput('isReturning', isReturning);
            core.setOutput('hasOkToTest', hasOkToTest);

      - name: Approve workflow run
        if: ${{ steps.check.outputs.isReturning == 'true' || steps.check.outputs.hasOkToTest == 'true' }}
        uses: actions/github-script@v6
        with:
          script: |
            const runId = context.runId;
            try {
              await github.actions.createWorkflowRunApproval({
                owner: context.repo.owner,
                repo: context.repo.repo,
                run_id: runId
              });
              console.log(`Approved workflow run ${runId}`);
            } catch (error) {
              console.log(`Could not approve workflow run: ${error.message}`);
            }
